        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=entry-date value="
                + (saved.getEntryDate() == null ? "" : saved.getEntryDate().toString()));
        return saved;
    }

    /** Change the sheet's grace days (null: off), auditing the change. */
    @Transactional
    public Sheet setGraceDays(String id, String user, Integer graceDays) {
        Sheet sheet = lock(id);
        sheet.setGraceDays(graceDays);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=grace-days value="
                + (saved.getGraceDays() == null ? "" : saved.getGraceDays().toString()));
        return saved;
    }

    /** Change the sheet's escalation gap in days (null: off), auditing the change. */
    @Transactional
    public Sheet setEscalateAfter(String id, String user, Integer days) {
        Sheet sheet = lock(id);
        sheet.setEscalateAfter(days);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=escalate-after value="
                + (saved.getEscalateAfter() == null ? "" : saved.getEscalateAfter().toString()));
        return saved;
    }

    /** Change the sheet's review SLA in days (null: none), auditing the change. */
    @Transactional
    public Sheet setReviewSla(String id, String user, Integer days) {
        Sheet sheet = lock(id);
        sheet.setReviewSla(days);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=review-sla value="
                + (saved.getReviewSla() == null ? "" : saved.getReviewSla().toString()));
        return saved;
    }

    /** Change the sheet's pending SLA in days (null: none), auditing the change. */
    @Transactional
    public Sheet setPendingSla(String id, String user, Integer days) {
        Sheet sheet = lock(id);
        sheet.setPendingSla(days);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=pending-sla value="
                + (saved.getPendingSla() == null ? "" : saved.getPendingSla().toString()));
        return saved;
    }

    /** Change the sheet's maximum of open claims per person (null: none), auditing the change. */
    @Transactional
    public Sheet setMaxOpen(String id, String user, Integer max) {
        Sheet sheet = lock(id);
        sheet.setMaxOpen(max);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=max-open value="
                + (saved.getMaxOpen() == null ? "" : saved.getMaxOpen().toString()));
        return saved;
