                + (saved.getScoreMid() == null ? "" : saved.getScoreMid().toString()));
        return saved;
    }

    /** Switch the sheet's score log on or off, auditing the change. */
    @Transactional
    public Sheet setScoreLog(String id, String user, boolean on) {
