363	            case "A" -> termsA;
364	            case "B" -> termsB;
365	            case "C" -> termsC;
366	            // A grade added to the sheet has no starting terms of its own.
367	            default -> null;
368	        };
369	        String value = valueOn(gradeTermsKey(grade), date, start == null ? null : start.toString());
370	        return value == null ? null : Integer.valueOf(value);
