772	    public int fiscalYearOf(LocalDate date) {
773	        return date.getMonthValue() >= fiscalStartMonth ? date.getYear() : date.getYear() - 1;
774	    }
775	
776	    /** The last claim number the sheet gave out in a fiscal year; 0 before any. */
777	    public int getLastClaimNumberIn(int fiscalYear) {
778	        return lastFiscalClaimNumbers.getOrDefault(fiscalYear, 0);
779	    }
780	
781	    /** Give out the next claim number in a fiscal year after the last given in it anywhere in the sheet's tree. */
782	    public int nextClaimNumberIn(int fiscalYear, int lastInTree) {
783	        int next = Math.max(getLastClaimNumberIn(fiscalYear), lastInTree) + 1;
784	        lastFiscalClaimNumbers.put(fiscalYear, next);
785	        return next;
786	    }
787	
788	    /** The roles set for an action, comma separated; null when it keeps its standing rule. */
789	    public String getPermission(String action) {
790	        return permissions.get(action);
791	    }
792	
793	    /** Set the roles that may take an action (null: the standing rule). */
794	    public void setPermission(String action, String roles) {
795	        if (roles == null) {
796	            permissions.remove(action);
797	        } else {
798	            permissions.put(action, roles);
799	        }
800	    }
801	
802	    /** Whether a role may take an action: the roles set for it, else its standing rule. */
803	    public boolean permits(String action, String role) {
804	        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
805	        // A restricted user name sees less of the people list, but acts as a clerk.
806	        String as = Role.RESTRICTED.equals(role) ? Role.CLERK : role;
807	        return Arrays.asList(roles.split(",")).contains(as);
808	    }
809	}
